<template><n-card :title="t('nav.favorites')" size="small"><template #header-extra><n-text depth="3">{{ favorites.length }} {{ t('favorites.count') }}</n-text></template>
  <n-empty v-if="!favorites.length" :description="t('favorites.empty')" />
  <n-space v-else vertical><n-card v-for="fav in favorites" :key="fav.name" size="small" hoverable>
    <n-space vertical><n-space justify="space-between"><n-space align="center"><n-text strong>{{ fav.displayName }}</n-text><n-tag size="tiny">{{ fav.category }}</n-tag><n-tag :type="fav.installed ? 'success' : fav.localVersion ? 'warning' : 'default'" size="tiny">{{ fav.installed ? t('status.installed') : fav.localVersion ? t('favorites.local_only') : t('favorites.not_installed') }}</n-tag></n-space><n-space><n-button data-action="detail" size="tiny" :aria-label="t('favorites.details')" :title="t('favorites.details')" @click="$emit('open-detail', fav)">...</n-button><n-button data-action="remove-favorite" size="tiny" secondary :aria-label="t('favorites.remove')" :title="t('favorites.remove')" class="fav-remove-btn" @click="$emit('remove-favorite', fav.name)">✕</n-button></n-space></n-space>
      <n-space align="center"><n-tag v-if="fav.activeVersion" type="success" size="small">{{ fav.activeVersion }}</n-tag><CopyableValue v-if="fav.localPath" :value="fav.localPath" /></n-space>
      <n-space><n-button v-if="!fav.installed && !fav.localVersion" data-action="install-latest" size="tiny" type="primary" @click="$emit('install-latest', fav)">{{ t('btn.install') }}</n-button><n-button v-if="!fav.installed && fav.localPath" data-action="migrate" size="tiny" type="primary" :disabled="migrationBusy" @click="$emit('migrate', fav.name, fav.localPath)">{{ t('detail.migrate_to_xdev') }}</n-button><n-button v-if="fav.installed" data-action="manage-versions" size="tiny" @click="$emit('manage-versions', fav)">{{ t('favorites.manage_versions') }}</n-button><n-button v-if="fav.installed && fav.localPath" data-action="switch-local" size="tiny" @click="$emit('switch-local', fav.name)">{{ t('detail.switch_to_local') }}</n-button></n-space>
      <div v-if="expandedName === fav.name"><n-divider/><n-text>{{ t('detail.installed_versions') }}</n-text><VersionList :versions="installedVersions" mode="installed" :t="t" @use="v => $emit('use-version', fav.name, v)" @uninstall="v => $emit('uninstall-version', fav.name, v)" @repair="v => $emit('repair', fav.name, v)"/><n-text>{{ t('detail.available_versions') }}</n-text><VersionList :versions="availableVersions" mode="available" :limit="5" :t="t" @install="v => $emit('install', fav.name, v)" @show-all="$emit('open-detail', fav)"/><n-space><input v-model="customVersion" data-testid="favorite-custom-version"/><n-button data-action="install-custom" size="tiny" :disabled="!customVersion" @click="$emit('install', fav.name, customVersion)">{{ t('btn.install') }}</n-button></n-space></div>
    </n-space></n-card></n-space>
</n-card></template>
<script setup>import { ref, watch } from 'vue';import { NButton, NCard, NDivider, NEmpty, NSpace, NTag, NText } from 'naive-ui';import CopyableValue from '../components/CopyableValue.vue';import VersionList from '../components/VersionList.vue';
const props=defineProps({favorites:{type:Array,default:()=>[]},expandedName:{type:String,default:''},installedVersions:{type:Array,default:()=>[]},availableVersions:{type:Array,default:()=>[]},t:{type:Function,required:true},
  // R8-02（第八轮审计，P1）：迁移进行中标志，透传自 AppContent 的
  // migratingSingle/migratingAll（与 F-40 对 EnvironmentVariablesPage 一致）。
  migrationBusy:{type:Boolean,default:false}});defineEmits(['open-detail','remove-favorite','install-latest','migrate','manage-versions','switch-local','use-version','uninstall-version','install','repair']);const customVersion=ref('');watch(()=>props.expandedName,()=>{customVersion.value=''});</script>
<style scoped>
.fav-remove-btn { color: var(--xdev-text-muted); transition: color var(--xdev-motion-fast), border-color var(--xdev-motion-fast); }
.fav-remove-btn:hover { color: var(--xdev-error); border-color: var(--xdev-error); }
</style>
